using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class PaymentVoucherRepository(NamaaDbContext db):IPaymentVoucherRepository{public Task<bool>ExistsByNumberAsync(string number,CancellationToken cancellationToken=default)=>db.PaymentVouchers.AsNoTracking().AnyAsync(x=>x.VoucherNumber==number,cancellationToken);public Task<PaymentVoucher?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.PaymentVouchers.AsNoTracking().Include(x=>x.Allocations).SingleOrDefaultAsync(x=>x.Id==id,cancellationToken);public Task<PaymentVoucher?>FindForUpdateAsync(long id,CancellationToken cancellationToken=default)=>db.PaymentVouchers.Include(x=>x.Allocations).SingleOrDefaultAsync(x=>x.Id==id,cancellationToken);public async Task<IReadOnlyList<PaymentVoucher>>GetAllAsync(CancellationToken cancellationToken=default)=>await db.PaymentVouchers.AsNoTracking().Include(x=>x.Allocations).OrderByDescending(x=>x.VoucherDate).ToListAsync(cancellationToken);public async Task AddAsync(PaymentVoucher entity,CancellationToken cancellationToken=default)=>await db.PaymentVouchers.AddAsync(entity,cancellationToken);}
